CREATE OR REPLACE FUNCTION calculate_tes(txkey_input INT)
RETURNS TEXT AS $ $
DECLARE 
    engagement_rating TEXT;
BEGIN
    SELECT therapy_details->>'engagement' 
    INTO engagement_rating
    FROM treatmentbasics
    WHERE txkey = txkey_input;
    
    RETURN engagement_rating;
END;
$ $ LANGUAGE plpgsql;

